DO $$
DECLARE def text;
BEGIN
  def := pg_get_functiondef('public.merge_student_account(uuid,uuid,text)'::regprocedure);
  def := replace(def,
    'UPDATE public.health_issues SET student_id = p_target_user_id WHERE student_id = p_source_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_moved := v_moved || jsonb_build_object(''health_issues'', v_n);',
    '-- Health-scan findings are diagnostic logs regenerated by every scan (100k+ rows per student); they are left in place.');
  IF position('UPDATE public.health_issues' in def) > 0 THEN
    RAISE EXCEPTION 'merge function patch did not apply';
  END IF;
  EXECUTE def;
END $$;